-- VNV Events Pasta Station location cycle, local batch 04 (cities 46-62).
SET NAMES utf8mb4;
DELIMITER $$
DROP PROCEDURE IF EXISTS vnv_pasta_b04_preflight$$
CREATE PROCEDURE vnv_pasta_b04_preflight() BEGIN
IF DATABASE()<>'ophyra' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Wrong local database'; END IF;
IF (SELECT COUNT(*) FROM cms_contents WHERE id_owner=2 AND site_key='vnvevents' AND slug IN ('pasta-station-catering-hallandale-beach','pasta-station-catering-dania-beach','pasta-station-catering-fort-lauderdale','pasta-station-catering-tamarac','pasta-station-catering-margate','pasta-station-catering-coconut-creek','pasta-station-catering-parkland','pasta-station-catering-oakland-park','pasta-station-catering-wilton-manors','pasta-station-catering-lighthouse-point','pasta-station-catering-aventura','pasta-station-catering-lauderdale-by-the-sea','pasta-station-catering-pembroke-park','pasta-station-catering-southwest-ranches','pasta-station-catering-hillsboro-beach','pasta-station-catering-sea-ranch-lakes','pasta-station-catering-west-park'))>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Pasta content collision'; END IF;
IF (SELECT COUNT(*) FROM cms_routes WHERE id_owner=2 AND site_key='vnvevents' AND route IN ('/locations/pasta-station-catering-hallandale-beach/','/locations/pasta-station-catering-dania-beach/','/locations/pasta-station-catering-fort-lauderdale/','/locations/pasta-station-catering-tamarac/','/locations/pasta-station-catering-margate/','/locations/pasta-station-catering-coconut-creek/','/locations/pasta-station-catering-parkland/','/locations/pasta-station-catering-oakland-park/','/locations/pasta-station-catering-wilton-manors/','/locations/pasta-station-catering-lighthouse-point/','/locations/pasta-station-catering-aventura/','/locations/pasta-station-catering-lauderdale-by-the-sea/','/locations/pasta-station-catering-pembroke-park/','/locations/pasta-station-catering-southwest-ranches/','/locations/pasta-station-catering-hillsboro-beach/','/locations/pasta-station-catering-sea-ranch-lakes/','/locations/pasta-station-catering-west-park/'))>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Pasta route collision'; END IF;
END$$
CALL vnv_pasta_b04_preflight()$$
DROP PROCEDURE vnv_pasta_b04_preflight$$
DELIMITER ;
SELECT id INTO @vnv_template_id FROM cms_templates WHERE id_owner=2 AND site_key='vnvevents' AND template_key='local-location-page' AND status='ACTIVE' LIMIT 1;
SELECT id INTO @vnv_category_id FROM cms_categories WHERE id_owner=2 AND site_key='vnvevents' AND slug='catering-services' AND is_active=1 AND applies_to_locations=1 LIMIT 1;
START TRANSACTION;
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
COMMIT;
SELECT COUNT(*) AS pasta_batch_01_contents FROM cms_contents WHERE id_owner=2 AND site_key='vnvevents' AND slug IN ('pasta-station-catering-hallandale-beach','pasta-station-catering-dania-beach','pasta-station-catering-fort-lauderdale','pasta-station-catering-tamarac','pasta-station-catering-margate','pasta-station-catering-coconut-creek','pasta-station-catering-parkland','pasta-station-catering-oakland-park','pasta-station-catering-wilton-manors','pasta-station-catering-lighthouse-point','pasta-station-catering-aventura','pasta-station-catering-lauderdale-by-the-sea','pasta-station-catering-pembroke-park','pasta-station-catering-southwest-ranches','pasta-station-catering-hillsboro-beach','pasta-station-catering-sea-ranch-lakes','pasta-station-catering-west-park');
SELECT COUNT(*) AS pasta_batch_01_routes FROM cms_routes WHERE id_owner=2 AND site_key='vnvevents' AND route IN ('/locations/pasta-station-catering-hallandale-beach/','/locations/pasta-station-catering-dania-beach/','/locations/pasta-station-catering-fort-lauderdale/','/locations/pasta-station-catering-tamarac/','/locations/pasta-station-catering-margate/','/locations/pasta-station-catering-coconut-creek/','/locations/pasta-station-catering-parkland/','/locations/pasta-station-catering-oakland-park/','/locations/pasta-station-catering-wilton-manors/','/locations/pasta-station-catering-lighthouse-point/','/locations/pasta-station-catering-aventura/','/locations/pasta-station-catering-lauderdale-by-the-sea/','/locations/pasta-station-catering-pembroke-park/','/locations/pasta-station-catering-southwest-ranches/','/locations/pasta-station-catering-hillsboro-beach/','/locations/pasta-station-catering-sea-ranch-lakes/','/locations/pasta-station-catering-west-park/') AND status='ACTIVE';
